package com.aria;
import com.aria.entity.*;
import com.aria.integration.*;
import com.aria.service.*;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Provider responses below are test doubles, never evidence of live OpenRouter E2E. */
@SpringBootTest(properties={"aria.smart-pricing.schedule-enabled=false","aria.connected-pricing.schedule-enabled=false","aria.intelligence.external-enabled=false","aria.seed-demo-catalog=false","aria.seed-demo-users=false","aria.manager.enabled=false","aria.manager.schedule-enabled=false","aria.store-sync.worker-enabled=false","aria.integrations.encryption-key=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","spring.datasource.url=${ARIA_TEST_DATABASE_URL:jdbc:h2:mem:connectedpricing;DB_CLOSE_DELAY=-1}","spring.datasource.username=${ARIA_TEST_DATABASE_USER:sa}","spring.datasource.password=${ARIA_TEST_DATABASE_PASSWORD:}","spring.datasource.driver-class-name=${ARIA_TEST_DATABASE_DRIVER:org.h2.Driver}","spring.flyway.enabled=${ARIA_TEST_FLYWAY:false}","spring.flyway.locations=classpath:db/migration/postgresql","spring.flyway.baseline-on-migrate=true","spring.flyway.baseline-version=0","spring.jpa.hibernate.ddl-auto=${ARIA_TEST_SCHEMA_MODE:update}","logging.level.root=ERROR"})
@Transactional
class ConnectedPricingIntegrationTest {
 @Autowired StoreSyncQueue syncQueue;@Autowired StoreAutonomyService autonomy;@Autowired ConnectedPricingService pricing;@Autowired StorePriceService permissions;@Autowired EntityManager em;@Autowired IntegrationVault vault;@Autowired ControlCenterService center;@Autowired WorkspaceOverviewService overview;@Autowired ManagerStore manager;
 @MockitoBean IntelligenceService ai;@MockitoBean WooCommerceReader woo;
 ConnectedStore store;StoreSnapshot item;SmartPricingSettings global;final AtomicReference<String> remote=new AtomicReference<>("1500.00");
 @BeforeEach void setup(){
  when(ai.pricingStatus()).thenReturn(Map.of("configured",true,"status","UNTESTED"));when(ai.decidePricing(anyMap())).thenReturn(model(5,false));
  store=new ConnectedStore();store.organization=em.find(Organization.class,1);store.name="Учебный внешний AI";store.platform="WOOCOMMERCE";store.baseUrl="https://connected.example.invalid";store.status="CONNECTED";store.catalogCurrency="KZT";store.currencyConfirmedAt=LocalDateTime.now();store.lastSync=LocalDateTime.now();store.lastOrdersSync=LocalDateTime.now();store.testConnection=true;em.persist(store);em.flush();
  item=new StoreSnapshot();item.storeId=store.id;item.externalId="10";item.name="Подтверждённый учебный товар";item.sku="CONNECTED-10";item.price=new BigDecimal("1500");item.currency="KZT";item.availableQuantity=18;item.observedAt=LocalDateTime.now();em.persist(item);
  var order=new StoreOrderSnapshot();order.storeId=store.id;order.externalId="100";order.status="completed";order.currency="KZT";order.total=new BigDecimal("22500");order.refundedTotal=BigDecimal.ZERO;order.createdAtUtc=LocalDateTime.now(ZoneOffset.UTC).minusDays(15);order.modifiedAtUtc=LocalDateTime.now(ZoneOffset.UTC);order.completedAtUtc=LocalDateTime.now(ZoneOffset.UTC).minusDays(1);order.observedAt=LocalDateTime.now();order.linesJson="[{\"productId\":\"10\",\"quantity\":15,\"total\":\"22500.00\"}]";em.persist(order);
  var access=new ExternalIntegration();access.store=store;access.provider="WOOCOMMERCE";access.status="READ_VERIFIED";access.encryptedCredentials=vault.encrypt("ck_"+"a".repeat(32)+"\ncs_"+"b".repeat(32));em.persist(access);
  global=em.find(SmartPricingSettings.class,1L);if(global==null){global=new SmartPricingSettings();em.persist(global);}global.externalAiEnabled=true;global.aiBudgetDate=LocalDate.now();global.aiBudgetUsed=0;global.lastAiRequestAt=null;em.flush();
  when(woo.currency(anyString(),anyString(),anyString())).thenReturn("KZT");when(woo.product(anyString(),nullable(String.class),anyString(),anyString(),anyString())).thenAnswer(call->live());when(woo.setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString())).thenAnswer(call->{remote.set(((BigDecimal)call.getArgument(3)).toPlainString());return live();});
 }
 private Map<String,Object> live(){var row=new LinkedHashMap<String,Object>();row.put("id",10);row.put("price",remote.get());row.put("regular_price",remote.get());row.put("sale_price","");row.put("manage_stock",true);row.put("stock_quantity",18);return row;}
 private Map<String,Object> model(int percent,boolean confirm){return Map.of("mode","AI","model","explicit-test-double:free","explanation","Проверка серверной валидации тестового ответа","risks",List.of(),"suggestedPercent",percent,"reviewAfterHours",1,"requiresConfirmation",confirm);}
 private void facts(boolean nonperishable){permissions.confirmProduct(store.id,"10",0,new BigDecimal("750"),new BigDecimal("1000"),"Текстиль",nonperishable,"Сведения учебной фикстуры, не реального магазина");}
 private void configure(String mode,boolean low){var p=permissions.settings(store.id);permissions.configure(store.id,store.version,((Number)p.get("version")).longValue(),mode,true,true,true,low,20,1,List.of("Текстиль"));}
 private long analyze(){return ((Number)pricing.analyze(store.id).getFirst().get("id")).longValue();}
 @Test void missingCostsRemainUnknownAndNeverCreateLocalInventory(){long before=em.createQuery("select count(p) from Product p",Long.class).getSingleResult();var d=pricing.analyze(store.id).getFirst();assertThat(d).containsEntry("status","NEEDS_DATA").containsEntry("source","ENGINE");assertThat(d.get("reason").toString()).contains("себестоимость");assertThat(em.createQuery("select count(p) from Product p",Long.class).getSingleResult()).isEqualTo(before);assertThat(em.createQuery("select count(l) from InventoryLot l",Long.class).getSingleResult()).isZero();verifyNoInteractions(woo);verify(ai,never()).decidePricing(anyMap());assertThat(center.center().get("openSignals")).isEqualTo(1L);assertThat(((Map<?,?>)overview.overview().get("risks")).get("openSignals")).isEqualTo(1L);}
 @Test void identicalAnalysisIsIdempotentAndChangedFactsCreateANewDecision(){facts(true);configure("RECOMMEND",false);long first=analyze();assertThat(analyze()).isEqualTo(first);item.availableQuantity=17;em.flush();long second=analyze();assertThat(second).isNotEqualTo(first);assertThat(em.find(StorePricingDecision.class,first).status).isEqualTo("SUPERSEDED");}
 @Test void bothCompanyAndPerStoreConsentsAreRequired(){facts(true);long firstId=analyze();assertThatThrownBy(()->pricing.decide(store.id,firstId,false)).hasMessageContaining("отдельное согласие");configure("RECOMMEND",false);long id=analyze();global.externalAiEnabled=false;em.flush();long finalId=id;assertThatThrownBy(()->pricing.decide(store.id,finalId,false)).hasMessageContaining("разрешите внешний AI");verify(ai,never()).decidePricing(anyMap());}
 @Test void recommendModeUsesEngineScenariosButWaitsForExplicitApproval(){facts(true);configure("RECOMMEND",true);long id=analyze();var result=pricing.decide(store.id,id,false);assertThat(result).containsEntry("source","AI").containsEntry("status","PENDING");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());assertThat(pricing.apply(store.id,id,false)).containsEntry("status","APPLIED");var change=permissions.history(store.id).getFirst();assertThat(change.source).isEqualTo("AI");assertThat(change.automatic).isFalse();assertThat(change.targetPrice).isEqualByComparingTo("1425");}
 @Test void explicitlyAllowedAutopilotIsRecordedWithTheActualWrite(){facts(true);configure("AUTOPILOT",true);long id=analyze();assertThat(pricing.decide(store.id,id,true)).containsEntry("status","APPLIED");var change=permissions.history(store.id).getFirst();assertThat(change.automatic).isTrue();assertThat(change.source).isEqualTo("AI");assertThat(global.aiBudgetUsed).isEqualTo(1);var dashboard=overview.overview();assertThat(((Map<?,?>)dashboard.get("today")).get("priceApplied")).isEqualTo(1L);assertThat((List<?>)center.center().get("connectedDecisions")).hasSize(1);}
 @Test void lowConfidenceOptInAndModelApprovalCannotBeBypassed(){facts(true);configure("AUTOPILOT",false);long id=analyze();assertThat(pricing.decide(store.id,id,true)).containsEntry("status","PENDING");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void aModelRequiringConfirmationNeverGetsAutopilot(){facts(true);configure("AUTOPILOT",true);when(ai.decidePricing(anyMap())).thenReturn(model(5,true));assertThat(pricing.decide(store.id,analyze(),true)).containsEntry("status","PENDING");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void tooLittleSalesHistoryBlocksAutomaticChangesEvenWithLowConfidencePermission(){facts(true);configure("AUTOPILOT",true);var order=em.createQuery("select o from StoreOrderSnapshot o where o.storeId=:id",StoreOrderSnapshot.class).setParameter("id",store.id).getSingleResult();order.createdAtUtc=LocalDateTime.now(ZoneOffset.UTC);order.linesJson="[{\"productId\":\"10\",\"quantity\":2,\"total\":\"3000\"}]";em.flush();assertThat(pricing.decide(store.id,analyze(),true)).containsEntry("status","PENDING");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void invalidStrategyIsReportedAsEngineAndNeverChangesPrices(){facts(true);configure("AUTOPILOT",true);when(ai.decidePricing(anyMap())).thenReturn(model(99,false));assertThat(pricing.decide(store.id,analyze(),true)).containsEntry("source","ENGINE");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void stockChangeDuringModelRequestInvalidatesItsAnswer(){facts(true);configure("AUTOPILOT",true);when(ai.decidePricing(anyMap())).thenAnswer(call->{item.availableQuantity=17;em.flush();return model(5,false);});assertThat(pricing.decide(store.id,analyze(),true)).containsEntry("status","STALE");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void budgetIsSharedAndExhaustionNeverContactsTheProvider(){facts(true);configure("AUTOPILOT",true);global.aiDailyBudget=1;global.aiBudgetUsed=1;em.flush();long id=analyze();assertThatThrownBy(()->pricing.decide(store.id,id,true)).hasMessageContaining("общий дневной лимит");assertThat(pricing.backgroundOne(store.id)).isFalse();verify(ai,never()).decidePricing(anyMap());}
 @Test void expiryIsNotInventedAndUnconfirmedPerishableGoodsCannotAutopilot(){facts(false);configure("AUTOPILOT",true);var result=pricing.analyze(store.id).getFirst();assertThat(result).containsEntry("status","NEEDS_DATA");when(ai.decidePricing(anyMap())).thenReturn(model(0,false));assertThat(pricing.decide(store.id,((Number)result.get("id")).longValue(),true)).containsEntry("source","AI").containsEntry("status","NEEDS_DATA");verifyNoInteractions(woo);}
 @Test void globalEmergencyStopAlsoRevokesExternalStoreWritesAndScheduledAi(){facts(true);configure("AUTOPILOT",true);manager.stop();assertThat(global.externalAiEnabled).isFalse();assertThat(store.writeEnabled).isFalse();assertThat(permissions.settings(store.id)).containsEntry("mode","RECOMMEND").containsEntry("priceWriteConsent",false).containsEntry("scheduledAiConsent",false);assertThat(pricing.backgroundOne(store.id)).isFalse();verifyNoInteractions(woo);verify(ai,never()).decidePricing(anyMap());}
 private StoreSyncQueue.Claim autonomous(boolean useAi){
  facts(true);item.availableQuantity=180;em.flush();
  when(woo.product(anyString(),nullable(String.class),anyString(),anyString(),anyString())).thenAnswer(call->{var row=live();row.put("stock_quantity",180);return row;});
  var settings=permissions.settings(store.id);permissions.configureAutonomy(store.id,store.version,((Number)settings.get("version")).longValue(),"AUTOPILOT",useAi,true,true,true,10,24,List.of("Текстиль"),60);syncQueue.requestCycle(store.id,false);return syncQueue.claim();
 }
 @Test void permittedEngineTrialWritesWithoutExternalAiAndNeverRepeatsWithinSevenDays(){
  var claim=autonomous(false);global.externalAiEnabled=false;em.flush();
  var result=pricing.autonomousBatch(claim,0);assertThat(result.applied()).isEqualTo(1);var change=permissions.history(store.id).getFirst();assertThat(change.source).isEqualTo("ENGINE");assertThat(change.automatic).isTrue();assertThat(change.status).isEqualTo("APPLIED");assertThat(change.targetPrice).isBetween(new BigDecimal("1425"),new BigDecimal("1485"));
  autonomy.finish(claim,new StoreAutonomyService.Outcome(1,0,1,result.cursor(),"Учебный результат"),null);
  var task=em.createQuery("select t from StoreSyncTask t where t.storeId=:id and t.operation='AUTONOMY'",StoreSyncTask.class).setParameter("id",store.id).getSingleResult();assertThat(task.state).isEqualTo("QUEUED");assertThat(task.dueAt).isAfter(LocalDateTime.now().plusMinutes(59));task.dueAt=LocalDateTime.now().minusSeconds(1);em.flush();
  assertThat(pricing.autonomousBatch(syncQueue.claim(),result.cursor()).applied()).isZero();verify(ai,never()).decidePricing(anyMap());verify(woo,times(1)).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());
 }
 @Test void realModelKeepIsNeverReplacedByAnEngineExperiment(){var claim=autonomous(true);when(ai.decidePricing(anyMap())).thenReturn(model(0,false));assertThat(pricing.autonomousBatch(claim,0).applied()).isZero();assertThat(pricing.list(store.id).getFirst()).containsEntry("source","AI").containsEntry("strategy","KEEP");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void modelRequestForOwnerApprovalCannotBeOverriddenByTrial(){var claim=autonomous(true);when(ai.decidePricing(anyMap())).thenReturn(model(5,true));assertThat(pricing.autonomousBatch(claim,0).applied()).isZero();assertThat(pricing.list(store.id).getFirst()).containsEntry("source","AI").containsEntry("confirmationRequired",true);verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void anExpiredWorkerLeaseCannotChangeThePrice(){var claim=autonomous(false);em.find(StoreSyncTask.class,claim.id()).leaseUntil=LocalDateTime.now().minusSeconds(1);em.flush();assertThatThrownBy(()->pricing.autonomousBatch(claim,0)).hasMessageContaining("отменён");verifyNoInteractions(woo);}
 @Test void pauseDuringPreflightCancelsTheAutomaticWrite(){var claim=autonomous(false);when(woo.currency(anyString(),anyString(),anyString())).thenAnswer(call->{var p=permissions.settings(store.id);autonomy.pause(store.id,((Number)p.get("version")).longValue());return "KZT";});assertThat(pricing.autonomousBatch(claim,0).applied()).isZero();assertThat(permissions.history(store.id).getFirst().status).isEqualTo("REJECTED");assertThat(permissions.settings(store.id)).containsEntry("autonomyEnabled",false);verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void changedGenerationDuringModelResponseCannotExecuteTheDecision(){var claim=autonomous(true);when(ai.decidePricing(anyMap())).thenAnswer(call->{syncQueue.requestCycle(store.id,true);return model(5,false);});assertThatThrownBy(()->pricing.autonomousBatch(claim,0)).hasMessageContaining("отменён");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void emergencyStopRevokesThePersistedEnginePermission(){var claim=autonomous(false);manager.stop();assertThat(permissions.settings(store.id)).containsEntry("autonomyEnabled",false).containsEntry("engineFallbackConsent",false);assertThat(syncQueue.isActive(claim)).isFalse();verifyNoInteractions(woo);}
 @Test void engineExperimentNeedsSeparateLowConfidencePermission(){facts(true);var p=permissions.settings(store.id);assertThatThrownBy(()->permissions.configureAutonomy(store.id,store.version,((Number)p.get("version")).longValue(),"AUTOPILOT",false,true,true,false,10,24,List.of("Текстиль"),60)).hasMessageContaining("низкую уверенность");verifyNoInteractions(woo);}

 @Test void pausedAutomationCannotBeBypassedThroughTheLegacySyncOrManualAiPath(){autonomous(true);var p=permissions.settings(store.id);autonomy.pause(store.id,((Number)p.get("version")).longValue());assertThat(pricing.backgroundOne(store.id)).isFalse();var d=pricing.decide(store.id,analyze(),false);assertThat(d).containsEntry("source","AI").containsEntry("status","PENDING");verify(woo,never()).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}
 @Test void threeInterruptedCyclesStayFailedUntilExplicitOwnerRetry(){var claim=autonomous(false);for(int i=0;i<3;i++){autonomy.finish(claim,null,"Учебный отказ соединения");var task=em.find(StoreSyncTask.class,claim.id());if(i<2){assertThat(task.state).isEqualTo("RETRY");task.dueAt=LocalDateTime.now().minusSeconds(1);em.flush();claim=syncQueue.claim();}}var task=em.find(StoreSyncTask.class,claim.id());assertThat(task.state).isEqualTo("FAILED");long generation=task.generation;syncQueue.requestCycle(store.id,false);assertThat(task.state).isEqualTo("FAILED");assertThat(task.generation).isEqualTo(generation);assertThat(syncQueue.claim()).isNull();assertThat((List<?>)autonomy.detail(store.id).get("runs")).hasSize(3);verifyNoInteractions(woo);}

 @Test void anAmbiguousAutomaticPutStopsTheBatchBeforeAnotherProductWrite(){var claim=autonomous(true);var other=new StoreSnapshot();other.storeId=store.id;other.externalId="20";other.name="Второй учебный товар";other.sku="SECOND-20";other.price=new BigDecimal("1500");other.currency="KZT";other.availableQuantity=180;other.observedAt=LocalDateTime.now();em.persist(other);em.flush();permissions.confirmProduct(store.id,"20",0,new BigDecimal("750"),new BigDecimal("1000"),"Текстиль",true,"Учебная проверка ограничения одного запроса");var order=em.createQuery("select o from StoreOrderSnapshot o where o.storeId=:id",StoreOrderSnapshot.class).setParameter("id",store.id).getSingleResult();order.linesJson="[{\"productId\":\"10\",\"quantity\":15,\"total\":\"22500\"},{\"productId\":\"20\",\"quantity\":15,\"total\":\"22500\"}]";em.flush();doThrow(new WooCommerceReader.WriteUncertain()).when(woo).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());assertThat(pricing.autonomousBatch(claim,0).applied()).isZero();assertThat(permissions.history(store.id)).hasSize(1);assertThat(permissions.history(store.id).getFirst().status).isEqualTo("VERIFY_REQUIRED");verify(woo,times(1)).setRegularPrice(anyString(),nullable(String.class),anyString(),any(),anyString(),anyString());}

}
